from form_function_common import *

def add_b11(b):
    code='B1.1';start=len(b.questions)
    def mc(key,title,stem,correct,wrong,why):b.add(code,key,title,stem,options=[correct]+wrong,reason=why)
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    mc('B11-carbon','Carbon as a molecular framework','Which property of carbon contributes most directly to the diversity of large biological molecules?','A carbon atom can form four covalent bonds, including bonds with other carbon atoms.',['Carbon can form only ionic bonds.','Carbon atoms cannot form rings.','Every carbon atom must bond to exactly four oxygen atoms.'],'Four covalent bonds allow chains, branched structures and rings with varied functional groups.')
    mc('B11-condensation','Joining two sugar monomers','Two monosaccharides join by a condensation reaction. What happens at the new linkage?','A glycosidic bond forms and a water molecule is released.',['A peptide bond forms and oxygen gas is released.','Water is consumed to split a glycosidic bond.','The carbon atoms are converted into nitrogen atoms.'],'Condensation joins the sugar units by a glycosidic linkage while removing the elements of water.')
    mc('B11-monosaccharide','A soluble respiratory substrate','Which pair of properties helps glucose function as a readily transported substrate for cellular respiration?','It is small and soluble in water.',['It forms insoluble cellulose fibres in blood.','It contains peptide bonds and a fixed three-dimensional active site.','It is completely non-polar and cannot interact with water.'],'The small, water-soluble molecule can be transported in aqueous fluids and used in respiration.')
    mc('B11-lipid-definition','Recognizing a lipid','Which property is shared by the lipids considered in this course?','They are largely insoluble in water and dissolve more readily in non-polar solvents.',['They are all long chains of amino acids.','They all contain repeating glucose units.','They must all contain three fatty acid chains.'],'Lipids are a chemically varied group defined in part by their low water solubility; phospholipids and steroids are not triglycerides.')
    q('B11-glucose-forms','One monomer formula, different polymers','Starch is assembled from alpha-glucose, whereas cellulose is assembled from beta-glucose.',P('Explain the relationship between the two glucose forms.',A('They have the same molecular formula but differ in the orientation of the hydroxy group on carbon 1.')),P('Explain how cellulose structure supports its role in plant cell walls.',A('Beta-glucose residues form straight, unbranched chains with alternating monomer orientation.'),R('Hydrogen bonds between adjacent chains organize them into strong microfibrils that resist tensile forces.')))
    q('B11-storage-polymers','Compact carbohydrate stores','A plant storage cell accumulates starch, while a mammalian liver cell accumulates glycogen.',P('State one shared structural feature and one difference between these storage carbohydrates.',A('Both are polymers of alpha-glucose.'),A('Glycogen is more highly branched; starch includes unbranched amylose and branched amylopectin.')),P('Explain two advantages of storing many glucose residues as a polymer.',R('A polymer has a much smaller osmotic effect than the same number of glucose residues as separate solute molecules.'),R('The compact store can be hydrolysed to release glucose when required; branch ends provide multiple sites for enzymatic release.')))
    q('B11-recognition','Carbohydrate labels on a cell surface','Two red blood cell types have different short carbohydrate chains attached to surface molecules. An antibody binds to one type but not the other.',P('Explain how these carbohydrates can contribute to cell recognition.',A('Different monosaccharide sequences and arrangements create different exposed molecular shapes.'),R('A recognition molecule such as an antibody binds selectively to a complementary carbohydrate structure.')),P('Distinguish a glycoprotein from a glycolipid.',A('A glycoprotein has carbohydrate attached to a protein; a glycolipid has carbohydrate attached to a lipid.')),P('Explain why antibody binding alone does not reveal the full sequence of a carbohydrate chain.',R('Binding shows recognition of an accessible region, but different longer molecules may share that region; structural analysis would be needed for the whole sequence.')))
    q('B11-triglyceride','Building an energy-storage lipid','A triglyceride is formed from one glycerol molecule and three fatty acid molecules.',P('State the type and number of links formed, and the number of water molecules released.',A('Three ester links form.'),A('Three water molecules are released.')),P('Explain why a triglyceride is well suited to long-term energy storage.',R('Its many carbon-hydrogen bonds provide a high energy yield per unit mass when oxidized.'),R('It is hydrophobic, so the store does not dissolve as many osmotically active particles in the cytoplasm.')))
    q('B11-fatty-acid-packing','A double bond changes packing','Two fatty acids have the same chain length. P is saturated; Q contains one cis carbon-carbon double bond.',P('Describe the structural difference and predict which packs more closely with neighbouring chains.',A('P has no carbon-carbon double bond; Q has a cis double bond that introduces a bend.'),A('P can pack more closely.')),P('Predict which has the lower melting temperature and explain.',A('Q has the lower melting temperature in this comparison.'),R('The bend reduces close contact and weakens the total intermolecular attractions between neighbouring chains.')))
    q('B11-phospholipid','An amphipathic molecule in water','A phospholipid has a polar phosphate-containing head and two non-polar fatty acid tails.',P('Explain the term amphipathic and predict the arrangement of many such molecules in a bilayer surrounded by water.',A('Amphipathic means that the molecule has both hydrophilic and hydrophobic regions.'),R('The heads face the aqueous environments on both sides, while the tails associate in the interior away from water.')),P('Explain why the interior of this bilayer limits the free passage of ions.',R('Charged ions interact unfavourably with the non-polar hydrophobic interior; a suitable transport protein is generally required.')))
    q('B11-steroids','Lipids with a different framework','Testosterone and oestradiol are steroid hormones. They are lipids but do not have the structure of a triglyceride.',P('State the characteristic carbon framework of a steroid and contrast it with that of a triglyceride.',A('A steroid has four fused carbon rings.'),A('A triglyceride has glycerol esterified to three fatty acid chains.')),P('Give one biological role of the named steroid hormones.',A('They act as chemical signals involved in reproductive development or function; accept a specific correct role for either named hormone.')))
    q('B11-insulation','Adipose tissue and heat loss','A mammal has a layer of adipose tissue beneath its skin.',P('Explain how this tissue can contribute both to energy storage and to thermal insulation.',A('Its cells store triglycerides that can be broken down and used as respiratory substrates.'),R('The lipid-rich layer conducts heat relatively poorly, reducing heat transfer from the body to colder surroundings.')),P('Explain why the amount of fat alone cannot determine an animal’s rate of heat loss.',R('Heat loss also depends on surface area, temperature difference, blood flow, body covering and environmental conditions; one specific factor with its effect is sufficient.')))
    energy=760;fat=38.0;carb=17.0
    q('B11-energy-data','Comparing fuel mass','For this constructed comparison, lipid supplies 38.0 kJ per gram and carbohydrate supplies 17.0 kJ per gram. An animal needs 760.0 kJ from its stored fuel. Ignore associated water and incomplete digestion.',P('Calculate the required mass of each fuel.',M('Divide required energy by energy per gram.'),A('Lipid: '+u(energy/fat,'g')+'; carbohydrate: '+u(energy/carb,'g')+'.')),P('Explain one advantage of lipid storage for a flying animal.',R('The same energy can be stored at a lower mass, reducing the mass that must be supported during flight.')),kind='data-based')
    chains=4;units=25;bonds=chains*(units-1)
    q('B11-hydrolysis-count','Counting links in a polymer model','A constructed model contains four separate, unbranched carbohydrate chains. Each chain contains exactly 25 glucose residues and has no ring closure. Complete hydrolysis breaks every glycosidic link.',P('Determine the total number of glycosidic links and water molecules consumed.',M('Each open chain of 25 residues has 24 links.'),A(f'There are {bonds} links in total; complete hydrolysis consumes {bonds} water molecules.')),P('Explain why this number differs from the total number of glucose residues.',R('Each separate open chain has one fewer link than residues; four separate chains therefore account for a difference of four between total residues and total links.')),kind='data-based')
    q('B11-emulsion-data','Interpreting a mixing experiment','Constructed observations are recorded after equal masses of glucose and a triglyceride are shaken separately with water. Glucose forms a clear solution. The triglyceride forms droplets that separate on standing.',P('Explain the different observations using molecular properties.',R('Glucose has polar hydroxy groups that interact with water, allowing it to dissolve.'),R('Most of the triglyceride surface is non-polar, so its molecules associate with one another rather than dissolve in water.')),P('Explain why a cloudy mixture immediately after shaking is not proof that the lipid has dissolved.',A('Small suspended droplets scatter light; dispersion as droplets is distinct from a molecular solution.')),P('Suggest a controlled comparison that would test the role of the solvent.',A('Repeat with a non-polar solvent, keeping solute mass, solvent volume, temperature and mixing time the same.')),kind='data-based')
    q('B11-unsaturation-data','Seed lipids in two growing conditions','A constructed investigation grows one plant genotype at two temperatures and measures the mean proportion of unsaturated fatty acid residues in seed triglycerides.'+table(['Growth temperature / °C','Mean unsaturated residues / %','Independent plants'],[(12,72,12),(24,49,12)]),P('Calculate the difference in unsaturated-residue percentage and describe the association.',A('The cooler-grown plants have 23 percentage points more unsaturated residues.'),A('Lower growth temperature is associated with a higher proportion of unsaturated residues in this dataset.')),P('Explain how this change could affect the physical state of the stored lipid.',R('More cis-unsaturated residues reduce close packing and lower melting temperature, helping the lipid remain less solid at lower temperature.')),P('State one further piece of evidence needed before concluding that the mean difference is reliable.',A('Accept variation among the independent plants, uncertainty intervals or an appropriate statistical comparison; mean values alone do not show variability.')),kind='data-based')
    b.extend(start+5,P('Classify ribose and glucose as pentose or hexose sugars, explaining the terms.',A('Ribose is a pentose with five carbon atoms.'),A('Glucose is a hexose with six carbon atoms.')))
    b.extend(start+10,P('Contrast the groups attached to glycerol in a typical phospholipid with those in a triglyceride.',A('A typical phospholipid has two fatty acid residues and a phosphate-containing polar group, whereas a triglyceride has three fatty acid residues.')))
    b.extend(start+11,P('Explain why these steroid hormones can pass through the hydrophobic region of a cell membrane.',R('Their largely non-polar steroid framework interacts with the hydrophobic lipid interior, allowing diffusion through the bilayer.')))
    b.extend(start+14,P('Explain why a triglyceride is not normally described as a polymer of repeated monomers.',A('It has one glycerol joined to only three fatty acid residues, rather than an extended chain of repeating monomer units.')))
    assert len(b.questions)-start==16

def add_b12(b):
    code='B1.2';start=len(b.questions)
    def mc(key,title,stem,correct,wrong,why,**kw):b.add(code,key,title,stem,options=[correct]+wrong,reason=why,**kw)
    def q(key,title,stem,*parts,**kw):b.add(code,key,title,stem,parts=list(parts),**kw)
    mc('B12-amino-acid','Interpreting an amino acid','The diagram uses a neutral structural convention for a general amino acid. What does X represent?','The side group that differs among amino acids.',['A second carboxyl group present in every amino acid.','A glucose polymer attached to every amino acid.','An electron that must be removed before protein synthesis.'],'The amino, carboxyl and hydrogen groups are shared features of this general model; variation in the side group produces different amino acids.',diagram=amino_svg())
    mc('B12-peptide','Joining protein monomers','Which groups react directly when a peptide bond forms between two amino acids?','The carboxyl group of one and the amino group of the other.',['Two side groups only.','Two alpha-carbon hydrogen atoms only.','Two phosphate groups.'],'Condensation between carboxyl and amino groups produces a peptide linkage and water.')
    mc('B12-essential','An essential amino acid','What does essential mean when describing an amino acid in a human diet?','The body cannot synthesize enough of it to meet its needs, so it must be obtained from food.',['It is used in every position of every protein.','It cannot be incorporated into a protein.','It is always the most abundant amino acid in muscle.'],'Essentiality concerns dietary supply relative to synthetic capacity, not how frequently an amino acid occurs in proteins.')
    mc('B12-denature','Loss of a functional shape','A treatment disrupts interactions maintaining a protein’s shape but does not hydrolyse its peptide bonds. Which change is expected?','Its three-dimensional structure may change while the amino acid sequence remains intact.',['Its amino acids are necessarily converted into glucose.','Every peptide bond must be broken.','Its sequence must be reversed.'],'Denaturation can disrupt folding without changing the primary amino acid sequence; function may be lost as shape changes.')
    q('B12-sequence-count','A model peptide library','A constructed model peptide has four positions. Each position can contain any one of three amino acid types, and repetition is allowed. Different orders count as different sequences.',P('Calculate the number of possible sequences.',M('Multiply three choices for each of four positions.'),A(m('3^{4}=81')+' sequences.')),P('Calculate the number of peptide bonds and water molecules released in forming one open-chain peptide of this length.',A('Three peptide bonds form and three water molecules are released.')),P('Explain why a change in sequence may alter protein function.',R('Changing the order of amino acids can change the interactions and final three-dimensional shape that determine function.')))
    q('B12-dipeptide','Drawing a short peptide','Two amino acids have side groups represented by '+m(r'R_1')+' and '+m(r'R_2')+'. Use the neutral structural convention.',P('Draw the dipeptide formed by joining the carboxyl group of the first amino acid to the amino group of the second.',A('The backbone contains '+m(r'\mathrm{-CH}(R_1)\mathrm{-C(=O)-NH-CH}(R_2)\mathrm{-}')+'.'),A('A free amino end and a free carboxyl end remain, and both side groups are retained.')),P('State the small molecule released and identify the bond broken during hydrolysis.',A('Water is released during condensation; hydrolysis breaks the carbonyl-carbon-to-nitrogen peptide bond by adding water.')),worked=amino_svg(True))
    q('B12-temperature-data','Testing persistent loss of protein function','In a constructed experiment, equal samples of a protein are held at different temperatures for 10 minutes, then all are returned to 25 °C before the same activity assay.'+table(['Pretreatment / °C','Activity relative to untreated sample / %'],[(25,100),(40,96),(60,38),(80,4)]),P('Describe the evidence for a persistent effect of high temperature.',A('Samples pretreated at 60 and 80 °C retain much less activity even though they are assayed at the same final temperature.')),P('Explain the result in terms of denaturation.',R('High temperature disrupts interactions maintaining the functional shape.'),R('The protein may fail to regain its original shape on cooling, so the binding or catalytic region is no longer correctly formed.')),P('Explain why all activity assays were performed at 25 °C.',A('This controls the immediate effect of assay temperature, allowing the persistent effect of pretreatment to be compared.')),kind='data-based')
    q('B12-diet-data','Complementary amino acid supplies','The following constructed food model lists amounts of two essential amino acids supplied by one standard serving. The model organism requires at least 1.0 unit of each per day; this is an abstract model, not a dietary recommendation.'+table(['Food','Amino acid P / units','Amino acid Q / units'],[('X',1.6,0.3),('Y',0.4,1.3)]),P('Determine whether one serving of X alone, one of Y alone, or one of each meets both requirements.',A('X alone is deficient in Q; Y alone is deficient in P.'),A('One of each supplies P = 2.0 units and Q = 1.6 units, meeting both model requirements.')),P('Explain why a range of protein sources can be useful in obtaining essential amino acids.',R('Different foods have different amino acid proportions, so one source can compensate for a limiting essential amino acid in another.')),kind='data-based')
    q('B12-r-groups','Protein surfaces in water','A soluble globular protein contains polar, charged and non-polar side groups.',P('Predict the typical positions of non-polar and polar side groups and explain.',A('Many non-polar groups are buried in the interior.'),R('Burial reduces their contact with water, while polar or charged groups often face the aqueous environment and interact with it.')),P('Explain why a membrane-spanning region can show the opposite surface pattern.',R('Its outward-facing non-polar side groups can interact favourably with the membrane’s hydrophobic interior.')),level='ahl')
    q('B12-secondary','Two regular folding patterns','A protein contains both alpha-helical and beta-sheet regions.',P('Describe the overall arrangement in each region.',A('An alpha helix is a coiled section of the polypeptide backbone.'),A('A beta sheet contains extended sections aligned alongside one another.')),P('State which interactions stabilize these secondary structures and where they form.',A('Hydrogen bonds form between backbone carbonyl oxygen and backbone N–H groups.'),R('They are not primarily bonds between the side groups; the repeated backbone can produce regular hydrogen-bonding patterns.')),level='ahl')
    q('B12-disulfide','A covalent contribution to folding','Two cysteine side groups in a folded protein form a disulfide link.',P('Identify the atoms joined and explain why this link can stabilize the protein.',A('A covalent sulfur-sulfur bond joins the two side groups.'),R('It holds distant parts of a chain, or different chains, in a particular relative arrangement.')),P('Distinguish this link from a peptide bond.',A('A disulfide joins cysteine side groups; peptide bonds join the amino acid backbone between carboxyl and amino groups.')),level='ahl')
    q('B12-ph-folding','Changing charge without changing sequence','A protein unfolds after a change in pH. Its peptide bonds remain intact.',P('Explain how pH can alter the folding interactions.',A('Changing pH changes the protonation and charge of some side groups.'),R('This can disrupt ionic attractions or create repulsion, changing the folding arrangement.')),P('State which structural level remains unchanged in this experiment and explain.',A('Primary structure remains unchanged because the order of amino acids and peptide-bond connections is preserved.')),level='ahl')
    q('B12-haemoglobin','A protein with more than polypeptides','Haemoglobin has four polypeptide subunits, each associated with an iron-containing haem group.',P('Explain why haemoglobin has quaternary structure and is a conjugated protein.',A('Quaternary structure describes the association of multiple polypeptide subunits.'),A('A conjugated protein contains a non-polypeptide component; here the haem groups are prosthetic groups.')),P('Link the haem group to haemoglobin function.',A('Oxygen binds reversibly at the iron-containing haem group, allowing oxygen transport and release.')),level='ahl')
    q('B12-insulin-collagen','Different protein forms','Insulin acts as a soluble signalling protein, whereas collagen forms strong extracellular fibres.',P('Contrast a globular and a fibrous protein.',A('Globular proteins fold into compact shapes; fibrous proteins form elongated structures that associate into fibres.')),P('Explain how collagen structure supports tensile strength.',A('Collagen has three polypeptide chains wound into a triple-helical arrangement.'),R('Interactions within and between aligned molecules resist pulling forces and support extracellular tissues.')),P('Explain why insulin’s folded shape matters to its role.',R('Its specific three-dimensional surface enables selective binding to its receptor; disruption of that shape can impair signalling.')),level='ahl')
    q('B12-sequence-folding','A side-group replacement','A mutation replaces one buried non-polar amino acid in a soluble protein with an amino acid whose side group is charged at the surrounding pH.',P('Suggest how this may affect folding.',R('A charged group buried in a hydrophobic interior may be energetically unfavourable and alter local interactions.'),R('The chain may rearrange to expose the group to water, potentially changing the overall shape.')),P('Explain why the mutation does not prove the protein has completely lost function.',A('The effect depends on position and on how much the relevant functional shape is changed; activity must be measured.')),level='ahl')
    q('B12-folding-data','Comparing protein stability','In a constructed study, a purified protein is tested before and after selective reduction of its disulfide bonds. The amino acid sequence is unchanged.'+table(['Sample','Temperature at which half the molecules are unfolded / °C'],[('Disulfide bonds intact',68),('Disulfide bonds reduced',49)]),P('Calculate the change and state the conclusion supported by the data.',A('Reduction lowers this unfolding midpoint by 19 °C.'),R('The intact disulfide links contribute to stability under the conditions tested.')),P('Explain why the result does not show that disulfide bonds are the only interactions maintaining the folded protein.',A('The reduced protein retains some stability; hydrogen bonds, ionic interactions and hydrophobic interactions can still contribute.')),P('State one control needed for a fair comparison.',A('Keep protein concentration, pH, buffer composition and heating protocol matched; one appropriate control is sufficient.')),level='ahl',kind='data-based')
    assert len(b.questions)-start==16
